#!/bin/bash
# 🦉 BuboIQ Automated Production Deployment Script
# Run from your "Bubo IQ Platform" folder on desktop
# This script handles everything: dependencies, git, database, vercel, edge functions

set -e  # Exit on any error

# Colors for beautiful output
GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
PURPLE='\033[0;35m'
CYAN='\033[0;36m'
NC='\033[0m' # No Color

# BuboIQ ASCII Art
echo -e "${GREEN}"
cat << "EOF"
██████╗ ██╗   ██╗██████╗  ██████╗ ██╗ ██████╗ 
██╔══██╗██║   ██║██╔══██╗██╔═══██╗██║██╔═══██╗
██████╔╝██║   ██║██████╔╝██║   ██║██║██║   ██║
██╔══██╗██║   ██║██╔══██╗██║   ██║██║██║▄▄ ██║
██████╔╝╚██████╔╝██████╔╝╚██████╔╝██║╚██████╔╝
╚═════╝  ╚═════╝ ╚═════╝  ╚═════╝ ╚═╝ ╚══▀▀═╝ 
                                               
🚀 Enterprise SaaS Platform - Production Deployment
EOF
echo -e "${NC}"

echo -e "${CYAN}🎯 Deploying your incredible enterprise platform...${NC}"
echo -e "${YELLOW}95+ React Components | Multi-Tenant Backend | Super Admin Console${NC}"
echo ""

# Function to check if command exists
command_exists() {
    command -v "$1" >/dev/null 2>&1
}

# Function to print step headers
print_step() {
    echo ""
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${BLUE}$1${NC}"
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo ""
}

# Function for success messages
print_success() {
    echo -e "${GREEN}✅ $1${NC}"
}

# Function for info messages  
print_info() {
    echo -e "${CYAN}ℹ️  $1${NC}"
}

# Function for warning messages
print_warning() {
    echo -e "${YELLOW}⚠️  $1${NC}"
}

# Function for error messages
print_error() {
    echo -e "${RED}❌ $1${NC}"
}

# Detect project directory
if [[ "$PWD" == *"Bubo IQ Platform"* ]]; then
    PROJECT_DIR="$PWD"
    print_success "Found BuboIQ project directory: $PROJECT_DIR"
elif [[ -d "$HOME/Desktop/Bubo IQ Platform" ]]; then
    PROJECT_DIR="$HOME/Desktop/Bubo IQ Platform"
    cd "$PROJECT_DIR"
    print_success "Found BuboIQ project directory: $PROJECT_DIR"
else
    print_error "Could not find 'Bubo IQ Platform' directory"
    echo -e "${YELLOW}Please run this script from your 'Bubo IQ Platform' folder or ensure it exists on your Desktop${NC}"
    exit 1
fi

# Verify this is the correct BuboIQ project
if [[ ! -f "App.tsx" ]] || [[ ! -f "package.json" ]] || [[ ! -d "components" ]]; then
    print_error "This doesn't appear to be your BuboIQ project directory"
    echo -e "${YELLOW}Expected files: App.tsx, package.json, components/ directory${NC}"
    exit 1
fi

print_success "Verified BuboIQ project structure"

# STEP 1: Prerequisites Check
print_step "Step 1: Prerequisites Check"

# Check for required tools
REQUIRED_TOOLS=("node" "npm" "git")
MISSING_TOOLS=()

for tool in "${REQUIRED_TOOLS[@]}"; do
    if command_exists "$tool"; then
        print_success "$tool is installed"
    else
        MISSING_TOOLS+=("$tool")
        print_error "$tool is not installed"
    fi
done

if [[ ${#MISSING_TOOLS[@]} -gt 0 ]]; then
    print_error "Missing required tools: ${MISSING_TOOLS[*]}"
    echo -e "${YELLOW}Please install the missing tools and run this script again${NC}"
    echo ""
    echo -e "${CYAN}Installation instructions:${NC}"
    echo -e "${YELLOW}• Node.js: https://nodejs.org/en/download/${NC}"
    echo -e "${YELLOW}• Git: https://git-scm.com/downloads${NC}"
    exit 1
fi

# STEP 2: Install Dependencies
print_step "Step 2: Installing Dependencies"

print_info "Installing project dependencies..."
npm install

print_info "Installing deployment tools..."
# Install Supabase CLI if not present
if ! command_exists supabase; then
    print_info "Installing Supabase CLI..."
    npm install -g supabase
    print_success "Supabase CLI installed"
else
    print_success "Supabase CLI already installed"
fi

# Install Vercel CLI if not present  
if ! command_exists vercel; then
    print_info "Installing Vercel CLI..."
    npm install -g vercel
    print_success "Vercel CLI installed"
else
    print_success "Vercel CLI already installed"
fi

# STEP 3: Git Repository Setup
print_step "Step 3: Git Repository Setup"

if [[ ! -d ".git" ]]; then
    print_info "Initializing Git repository..."
    git init
    git add .
    git commit -m "🚀 BuboIQ Production Launch - Enterprise SaaS Platform

    ✅ Complete Marketing Website (8+ pages)
    ✅ Full SaaS Application with authentication  
    ✅ Super Admin Master Console
    ✅ Knowledge Base System
    ✅ Remote Connect Platform
    ✅ Agent Management System
    ✅ Multi-Tenant Backend (12+ API endpoints)
    ✅ Production Security (JWT, RLS policies)"
    git branch -M main
    print_success "Git repository initialized"
else
    print_warning "Git repository already exists"
fi

# STEP 4: GitHub Repository Creation
print_step "Step 4: GitHub Repository Setup"

echo -e "${CYAN}Please create a GitHub repository:${NC}"
echo -e "${YELLOW}1. Open: https://github.com/new${NC}"
echo -e "${YELLOW}2. Repository name: buboiq${NC}"  
echo -e "${YELLOW}3. Click 'Create repository'${NC}"
echo ""

read -p "Enter your GitHub username: " GITHUB_USERNAME

if [[ -z "$GITHUB_USERNAME" ]]; then
    print_error "GitHub username is required"
    exit 1
fi

print_info "Adding GitHub remote..."
git remote add origin "https://github.com/$GITHUB_USERNAME/buboiq.git" 2>/dev/null || git remote set-url origin "https://github.com/$GITHUB_USERNAME/buboiq.git"

print_info "Pushing to GitHub..."
if git push -u origin main; then
    print_success "Code pushed to GitHub: https://github.com/$GITHUB_USERNAME/buboiq"
else
    print_error "Failed to push to GitHub"
    echo -e "${YELLOW}Please check:${NC}"
    echo -e "${YELLOW}• Repository exists at: https://github.com/$GITHUB_USERNAME/buboiq${NC}"
    echo -e "${YELLOW}• You have push permissions${NC}"
    exit 1
fi

# STEP 5: Database Schema Deployment
print_step "Step 5: Database Schema Deployment"

print_info "Opening Supabase SQL Editor..."
echo -e "${YELLOW}Manual step required:${NC}"
echo -e "${CYAN}1. Go to: https://supabase.com/dashboard/project/xwcgpmqgqysxeovbrbxg/sql/new${NC}"
echo -e "${CYAN}2. Copy the ENTIRE contents of DEPLOY_SCHEMA.sql from your project${NC}"
echo -e "${CYAN}3. Paste into the SQL Editor and click 'Run'${NC}"
echo ""

# Open the file for easy copying (macOS)
if command_exists open && [[ -f "DEPLOY_SCHEMA.sql" ]]; then
    print_info "Opening DEPLOY_SCHEMA.sql for easy copying..."
    open "DEPLOY_SCHEMA.sql"
fi

read -p "Press ENTER after you've deployed the database schema..."
print_success "Database schema deployment confirmed"

# STEP 6: Vercel Deployment  
print_step "Step 6: Vercel Deployment"

print_info "Logging into Vercel..."
vercel login

print_info "Deploying to Vercel with environment variables..."
vercel --prod \
  -e SUPABASE_URL=https://xwcgpmqgqysxeovbrbxg.supabase.co \
